import {initial,advance,shift,replay,validSave} from './model.js';
import {renderWorld} from './world.js';
let state=initial(),close=false,canSave=true;
try{const raw=localStorage.getItem('life-study-v1');if(raw){const saved=JSON.parse(raw);if(validSave(saved))state=saved;}}catch{canSave=false;}
const $=id=>document.getElementById(id);const money=n=>'฿'+n.toLocaleString('en');
const titles=['You arrive.','A wider world.','A week of your own.'];
const stories=['Your mother runs a food stall. Your father repairs motorbikes. Tonight, the three of you are home.','Six years pass. The same street now leads to school. Your family still needs help, and there are friends waiting outside.','After school, 12 hours remain. Your family needs help. Your friends are outside.'];
const labels={stall:['Family stall','฿15 per hour'],study:['Study','Time at your desk'],friends:['Friends','Time together']};
function draw(){const done=state.week===4;$('age').textContent='Age '+[0,6,12][state.chapter];$('place').textContent=state.chapter===0?'Your family home':'Home & the neighborhood';$('chapter-label').textContent=['01 / A beginning','02 / The street outside',`03 / Week ${Math.min(state.week+1,4)} of 4`][state.chapter];$('title').textContent=done?'The same month. Another life?':titles[state.chapter];$('story').textContent=done?'The rain was outside your control. How you spent your time was yours. Replay this month and compare the trade-offs.':stories[state.chapter];$('allocation').hidden=state.chapter!==2||done;$('next').textContent=done?'Try another path →':state.chapter===0?'Meet your family →':state.chapter===1?'Step forward to age 12 →':'Live this week →';$('cash').textContent=money(state.cash);$('learning').textContent=state.learning+' h';$('bonds').textContent=state.bonds+' h';$('scene-note').textContent=state.chapter===0?'A family. A room. A beginning.':state.week===2?'Rain damaged the stall’s supplies.':state.learning>0?'Your notebooks hold the hours you gave them.':'Home, school, the stall.';
$('time-controls').replaceChildren();for(const key of Object.keys(labels)){const row=document.createElement('div');row.className='time-row';const label=document.createElement('span');label.textContent=labels[key][0];const small=document.createElement('small');small.textContent=labels[key][1];label.append(small);const output=document.createElement('output');output.textContent=state.plan[key]+' h';const minus=document.createElement('button'),plus=document.createElement('button');for(const [b,d,t]of [[minus,-2,'−'],[plus,2,'+']]){b.type='button';b.textContent=t;b.setAttribute('aria-label',(d>0?'Add two hours to ':'Remove two hours from ')+labels[key][0]);b.disabled=d<0?state.plan[key]<2:state.plan[key]>10;b.onclick=()=>{const focus=b.getAttribute('aria-label');state={...state,plan:shift(state.plan,key,d)};draw();document.querySelector(`[aria-label="${focus}"]`)?.focus();};}row.append(label,minus,output,plus);$('time-controls').append(row);}
$('time-track').replaceChildren();for(const key of Object.keys(labels))for(let i=0;i<state.plan[key];i++){const cell=document.createElement('span');cell.dataset.kind=key;$('time-track').append(cell)}$('forecast').textContent=`12 / 12 hours assigned · Stall earnings ${money(state.plan.stall*15)} before household costs.`;
const e=state.history.at(-1);$('outcome').textContent=e?`Week ${e.week}: +${money(e.earned)} earned, −${money(e.cost)} household costs.${e.rain?' Heavy rain damaged supplies. Every replay has this same event.':''}`:'';if(done&&state.baseline){const diff=(v,b)=>`${v-b>=0?'+':''}${v-b}`;$('outcome').textContent+=` Compared with your previous path: ${diff(state.cash,state.baseline.cash)} baht, ${diff(state.learning,state.baseline.learning)} study hours, ${diff(state.bonds,state.baseline.bonds)} hours with friends.`;}$('save-note').textContent=canSave?'Fictional scenario · saved in this browser':'Fictional scenario · browser save unavailable';renderWorld($('scene'),state,close);try{localStorage.setItem('life-study-v1',JSON.stringify(state));}catch{canSave=false;$('save-note').textContent='Fictional scenario · browser save unavailable';}}
$('next').onclick=()=>{state=state.week===4?replay(state):advance(state);draw()};$('restart').onclick=()=>{state=initial();draw()};$('view').onclick=()=>{close=!close;$('view').textContent=close?'See neighborhood':'Look closer';draw()};draw();
